// src/pages/Dashboard.js
import React, { useState, useEffect} from "react";
import axios from 'axios'

const API = 'http://127.0.0.1:8080';

function Dashboard() {
    const [stocks, setStocks] = useState([]);
    const [loading, setLoading] = useState(true);

    const fetchPrices = async () => {
        try {
            const res = await axios.get(`${API}/watchlist/prices`);
            setStocks(res.data.data);
        } catch(e) {
            console.error('시세 조회 실패😱:', e);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchPrices();
        // 60초마다 자동 갱신
        const interval = setInterval(fetchPrices, 60000);
        return () => clearInterval(interval);
    }, []);

    return (
        <div>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '24px'}}>
                <h2 style={{ fontsize: '20px'}}>📈 메뚜기의 라이브 대시보드</h2>
                <button className="btn btn=primary" onClick={fetchPrices}>
                    🔁 헤이, 리로드!
                </button>
            </div>

            {loading ? (
                <p style={{ color: '#8b949e'}}>⌚로딩 중..</p>
            ) : stocks.length === 0 ? (
                <div className="card">
                    <p style={ {color: '#8b949e'}}>관심종목이 없어, 설정에서 추가해볼까?🦗</p>
                </div>
            ) : (
                <div className="grid">
                    {stocks.map((stock, idx) => (
                        <StockCard key={idx} stock={stock} />
                    ))}
                </div>
            )}
        </div>
    );
}

function StockCard({ stock }) {
    const changeRate = parseFloat(stock.change_rate || 0);
    const isUp = changeRate >= 0;
    const price = parseInt(stock.price || 0).toLocaleString();
    const change = parseInt(stock.change || 0).toLocaleString();

    return (
        <div className="stock-card">
            <div clalssName="ticker">{stock.ticker}</div>
            <div className="name">{stock.name || stock.ticker}</div>
            <div className="price">{price}원</div>
            <div className={`change ${isUp ? 'up' : 'down'}`}>
                {isUp ? '▲' : '▼'} {change}원 ({changeRate}%)
            </div>
            <div className="indicators7">
                <span className="indicator">거래량 {parseInt(stock.volume || 0).toLocaleString()}</span>
            </div>
        </div>
    );
}

export default Dashboard;
